-- USMLE Step 1 Full 280-Question Migration
-- Focus: Pathology (44-52%), Physiology (25-35%), Anatomy (10-20%)
-- Mapping all questions to 12 USMLE Topics

DO $$
DECLARE
    v_micro_id UUID;
    v_beh_id UUID;
    v_pharm_id UUID;
    v_physio_id UUID;
    v_biostat_id UUID;
    v_anatomy_id UUID;
    v_path_id UUID;
    v_biochem_id UUID;
    v_inter_id UUID;
    v_nutri_id UUID;
    v_aging_id UUID;
    v_genetics_id UUID;
BEGIN
    -- 1. Get Topic IDs
    SELECT id INTO v_micro_id FROM public.topics WHERE title = 'Microbiology' AND usmle_step = 1;
    SELECT id INTO v_beh_id FROM public.topics WHERE title = 'Behavioural sciences' AND usmle_step = 1;
    SELECT id INTO v_pharm_id FROM public.topics WHERE title = 'Pharmacology' AND usmle_step = 1;
    SELECT id INTO v_physio_id FROM public.topics WHERE title = 'Physiology' AND usmle_step = 1;
    SELECT id INTO v_biostat_id FROM public.topics WHERE title = 'Biostatistics and Epidemiology' AND usmle_step = 1;
    SELECT id INTO v_anatomy_id FROM public.topics WHERE title = 'Anatomy' AND usmle_step = 1;
    SELECT id INTO v_path_id FROM public.topics WHERE title = 'Pathology' AND usmle_step = 1;
    SELECT id INTO v_biochem_id FROM public.topics WHERE title = 'Biochemistry' AND usmle_step = 1;
    SELECT id INTO v_inter_id FROM public.topics WHERE title = 'Inter-disciplines' AND usmle_step = 1;
    SELECT id INTO v_genetics_id FROM public.topics WHERE title = 'Genetics' AND usmle_step = 1;

    -- 2. Cleanup existing MCQs for these Step 1 topics to prevent duplicates
    DELETE FROM public.mcqs WHERE topic_id IN (v_micro_id, v_beh_id, v_pharm_id, v_physio_id, v_biostat_id, v_anatomy_id, v_path_id, v_biochem_id, v_inter_id, v_genetics_id);

    -- 3. Insert BLOCK 1 (Microbiology & Pharmacology: Q1-40)
    INSERT INTO public.mcqs (topic_id, question, options, correct_index, explanation, "order") VALUES
    (v_micro_id, 'A 35-year-old male develops a UTI. Culture grows a gram-negative rod: oxidase-positive, non-lactose fermenting, blue-green pigment, fruity odor. Which virulence factor primarily confers resistance to most beta-lactam antibiotics?', '["Protein A", "AmpC beta-lactamase", "Leukocidin", "Capsular polysaccharide", "Coagulase"]', 1, 'Block 1 — Q1. Explanation: Pseudomonas aeruginosa has chromosomally encoded, inducible AmpC beta-lactamase.', 1),
    (v_pharm_id, 'A patient with Parkinson''s disease is started on a drug that inhibits dopamine metabolism in the synaptic cleft. Which enzyme is target by Entacapone?', '["Monoamine oxidase-B", "DOPA decarboxylase", "Catechol-O-methyltransferase (COMT)", "Tyrosine hydroxylase", "Acetylcholinesterase"]', 2, 'Block 1 — Q2. Explanation: Entacapone and tolcapone are COMT inhibitors.', 2),
    (v_micro_id, 'A 4-year-old child presents with high fever, sore throat, and a "cherry-red" epiglottis. The causative agent is a gram-negative coccobacillus that requires Factor V (NAD) and Factor X (hemin) for growth. What is the most likely organism?', '["Streptococcus pyogenes", "Haemophilus influenzae type b", "Corynebacterium diphtheriae", "Neisseria meningitidis", "Bordetella pertussis"]', 1, 'Block 1 — Q3. Explanation: Epiglottitis is typically caused by H. influenzae type b.', 3),
    (v_pharm_id, 'A drug that binds to a receptor and produces a submaximal response even at 100% receptor occupancy is known as a:', '["Full agonist", "Partial agonist", "Antagonist", "Inverse agonist", "Competitive inhibitor"]', 1, 'Block 1 — Q4. Explanation: Partial agonists have lower intrinsic activity.', 4),
    (v_micro_id, 'A 24-year-old male presents with painful urination and purulent urethral discharge. Gram stain shows gram-negative diplococci within neutrophils. What is the standard treatment?', '["Penicillin G", "Ceftriaxone + Azithromycin", "Ciprofloxacin", "Metronidazole", "Doxycycline alone"]', 1, 'Block 1 — Q5. Explanation: Neisseria gonorrhoeae is treated with ceftriaxone.', 5),
    (v_micro_id, 'Which of the following is the most common cause of neonatal meningitis?', '["Listeria monocytogenes", "Escherichia coli", "Group B Streptococcus", "Haemophilus influenzae", "Neisseria meningitidis"]', 2, 'Block 1 — Q6. Explanation: Group B Strep (S. agalactiae) is the leading cause.', 6),
    (v_pharm_id, 'A 60-year-old male on treatment for pulmonary tuberculosis develops numbness and tingling in his hands and feet. This side effect is caused by a deficiency of which vitamin?', '["Vitamin B1 (Thiamine)", "Vitamin B6 (Pyridoxine)", "Vitamin B12 (Cobalamin)", "Vitamin B3 (Niacin)", "Vitamin B9 (Folate)"]', 1, 'Block 1 — Q7. Explanation: Isoniazid causes peripheral neuropathy by depleting B6.', 7),
    (v_micro_id, 'A patient presents with a painless chancre on their genitals. Dark-field microscopy reveals spirochetes. What is the drug of choice?', '["Azithromycin", "Doxycycline", "Penicillin G", "Ciprofloxacin", "Gentamicin"]', 2, 'Block 1 — Q8. Explanation: Treponema pallidum (Syphilis) is treated with Penicillin G.', 8),
    (v_pharm_id, 'Which of the following diuretics works by inhibiting the Na+/K+/2Cl- cotransporter in the thick ascending limb of the loop of Henle?', '["Hydrochlorothiazide", "Spironolactone", "Furosemide", "Acetazolamide", "Mannitol"]', 2, 'Block 1 — Q9. Explanation: Furosemide is a loop diuretic.', 9),
    (v_micro_id, 'A 22-year-old female presents with a "clue cell" appearance on vaginal smear and a fishy odor. What is the most likely diagnosis?', '["Trichomoniasis", "Candidiasis", "Bacterial Vaginosis", "Gonorrhea", "Chlamydia"]', 2, 'Block 1 — Q10. Explanation: Bacterial Vaginosis is caused by Gardnerella vaginalis.', 10),
    (v_pharm_id, 'A 45-year-old female with hypertension is started on a medication that causes a dry cough. Which class of drug was most likely prescribed?', '["Beta-blockers", "Calcium channel blockers", "ACE inhibitors", "ARBs", "Thiazide diuretics"]', 2, 'Block 1 — Q11. Explanation: ACE inhibitors increase bradykinin, causing cough.', 11),
    (v_micro_id, 'Which virus is the primary cause of cervical cancer and is associated with E6 and E7 proteins that inhibit p53 and Rb?', '["HSV-2", "HPV types 16 and 18", "CMV", "EBV", "HIV"]', 1, 'Block 1 — Q12. Explanation: HPV 16 and 18 are high-risk types.', 12),
    (v_pharm_id, 'The mechanism of action of Aspirin involves irreversible inhibition of which enzyme?', '["COX-2 only", "Lipoxygenase", "Cyclooxygenase (COX-1 and COX-2)", "Phospholipase A2", "Thromboxane synthase"]', 2, 'Block 1 — Q13. Explanation: Aspirin binds irreversibly to COX via acetylation.', 13),
    (v_micro_id, 'A 40-year-old hunter presents with a high fever, headache, and a skin ulcer. He recently handled a rabbit. What is the most likely pathogen?', '["Pasteurella multocida", "Francisella tularensis", "Yersinia pestis", "Brucella melitensis", "Borrelia burgdorferi"]', 1, 'Block 1 — Q14. Explanation: Tularemia is associated with rabbit exposure.', 14),
    (v_pharm_id, 'Which antibiotic works by binding to the 50S ribosomal subunit and inhibiting translocation?', '["Tetracycline", "Gentamicin", "Erythromycin", "Penicillin", "Ciprofloxacin"]', 2, 'Block 1 — Q15. Explanation: Macrolides (Erythromycin) bind the 50S subunit.', 15),
    (v_micro_id, 'A 30-year-old HIV+ patient has a CD4 count <50. He develops a systemic infection with acid-fast bacilli that are non-tuberculous. What is the most likely organism?', '["Mycobacterium avium complex (MAC)", "Mycobacterium leprae", "Mycobacterium kansasii", "Mycobacterium scrofulaceum", "Mycobacterium marinum"]', 0, 'Block 1 — Q16. Explanation: MAC is common in advanced AIDS.', 16),
    (v_pharm_id, 'Which drug is a direct thrombin inhibitor used as an alternative to heparin in patients with Heparin-Induced Thrombocytopenia (HIT)?', '["Warfarin", "Argatroban", "Enoxaparin", "Fondaparinux", "Rivaroxaban"]', 1, 'Block 1 — Q17. Explanation: Argatroban is a direct thrombin inhibitor.', 17),
    (v_micro_id, 'Which toxin acts by ADP-ribosylation of elongation factor 2 (EF-2), leading to inhibition of protein synthesis?', '["Tetanospasmin", "Diphtheria toxin", "Cholera toxin", "Shiga toxin", "Anthrax lethal factor"]', 1, 'Block 1 — Q18. Explanation: Diphtheria toxin and Pseudomonas exotoxin A inhibit EF-2.', 18),
    (v_pharm_id, 'A patient with major depressive disorder is started on Fluoxetine. What is the mechanism of action of this drug?', '["Inhibition of MAO", "Selective inhibition of serotonin reuptake (SSRI)", "Inhibition of norepinephrine reuptake", "Antagonism of 5-HT2 receptors", "D2 receptor blockade"]', 1, 'Block 1 — Q19. Explanation: Fluoxetine is an SSRI.', 19),
    (v_micro_id, 'A 7-year-old boy has honey-colored crusts around his mouth. Culture grows catalase-positive, coagulase-positive cocci in clusters. What is the organism?', '["Streptococcus pyogenes", "Staphylococcus aureus", "Staphylococcus epidermidis", "Streptococcus pneumoniae", "Streptococcus agalactiae"]', 1, 'Block 1 — Q20. Explanation: Impetigo with coagulase+ cocci is S. aureus.', 20),
    (v_pharm_id, 'Which of the following is a competitive antagonist of the H1 histamine receptor used to treat allergic reactions?', '["Ranitidine", "Diphenhydramine", "Omeprazole", "Misoprostol", "Cimetidine"]', 1, 'Block 1 — Q21. Explanation: Diphenhydramine is a first-generation H1 blocker.', 21),
    (v_micro_id, 'A 19-year-old college student presents with meningitis. Gram stain reveals gram-negative diplococci. Which vaccine could have prevented this?', '["Hib vaccine", "PCV13", "Meningococcal vaccine", "MMR", "Tdap"]', 2, 'Block 1 — Q22. Explanation: N. meningitidis is a common cause in young adults.', 22),
    (v_pharm_id, 'Which statin medication works by inhibiting HMG-CoA reductase, the rate-limiting enzyme in cholesterol synthesis?', '["Gemfibrozil", "Atorvastatin", "Ezetimibe", "Cholestyramine", "Niacin"]', 1, 'Block 1 — Q23. Explanation: Atorvastatin is an HMG-CoA reductase inhibitor.', 23),
    (v_micro_id, 'A patient from Ohio presents with calcified lung nodules after cleaning a chicken coop. What is the most likely fungal pathogen?', '["Coccidioides immitis", "Histoplasma capsulatum", "Blastomyces dermatitidis", "Paracoccidioides brasiliensis", "Sporothrix schenckii"]', 1, 'Block 1 — Q24. Explanation: Histoplasmosis is associated with bird/bat droppings in Ohio/Mississippi valleys.', 24),
    (v_pharm_id, 'Which drug is a loop diuretic that can cause ototoxicity, especially when used with aminoglycosides?', '["Spironolactone", "Furosemide", "Triamterene", "Chlorthalidone", "Acetazolamide"]', 1, 'Block 1 — Q25. Explanation: Loop diuretics like Furosemide are ototoxic.', 25),
    (v_micro_id, 'Which organism is known for "swarming" motility on agar and is a common cause of staghorn calculi?', '["Escherichia coli", "Proteus mirabilis", "Pseudomonas aeruginosa", "Klebsiella pneumoniae", "Serratia marcescens"]', 1, 'Block 1 — Q26. Explanation: Proteus produces urease, leading to struvite stones.', 26),
    (v_pharm_id, 'The antibiotic Vancomycin works by inhibiting which process?', '["DNA replication", "Protein synthesis (30S)", "Cell wall synthesis (D-Ala-D-Ala)", "Folate synthesis", "RNA transcription"]', 2, 'Block 1 — Q27. Explanation: Vancomycin binds D-Ala-D-Ala to inhibit peptidoglycan cross-linking.', 27),
    (v_micro_id, 'A 50-year-old male with cirrhosis develops a fever and abdominal pain. Paracentesis shows >250 neutrophils/mL. What is the most likely diagnosis?', '["Acute Cholecystitis", "Spontaneous Bacterial Peritonitis", "Acute Pancreatitis", "Appendicitis", "Biliary Colic"]', 1, 'Block 1 — Q28. Explanation: SBP is common in cirrhosis, often caused by E. coli.', 28),
    (v_pharm_id, 'Which anti-diabetic drug acts by activating PPAR-gamma to increase insulin sensitivity in peripheral tissues?', '["Metformin", "Pioglitazone", "Glyburide", "Sitagliptin", "Acarbose"]', 1, 'Block 1 — Q29. Explanation: Thiazolidinediones (glitazones) activate PPAR-gamma.', 29),
    (v_micro_id, 'Which helminth infection is associated with Vitamin B12 deficiency due to competition for the vitamin in the host gut?', '["Ascaris lumbricoides", "Enterobius vermicularis", "Diphyllobothrium latum", "Necator americanus", "Strongyloides stercoralis"]', 2, 'Block 1 — Q30. Explanation: The fish tapeworm D. latum absorbs host Vitamin B12.', 30),
    (v_pharm_id, 'Which of the following is a non-depolarizing neuromuscular blocker used during surgery?', '["Succinylcholine", "Vecuronium", "Neostigmine", "Atropine", "Dantrolene"]', 1, 'Block 1 — Q31. Explanation: Vecuronium is a competitive ACh antagonist at the motor end plate.', 31),
    (v_micro_id, 'A patient presents with a thick "pseudomembrane" in the pharynx. The causative organism is gram-positive and produces a toxin that inhibits EF-2. What is the organism?', '["Streptococcus pyogenes", "Corynebacterium diphtheriae", "Arcanobacterium haemolyticum", "Actinomyces israelii", "Nocardia asteroides"]', 1, 'Block 1 — Q32. Explanation: Diphtheria is characterized by the pseudomembrane.', 32),
    (v_pharm_id, 'A 25-year-old female is started on an antidepressant that can cause a hypertensive crisis if she eats foods high in tyramine (like aged cheese). What is the class of this drug?', '["SSRI", "TCAs", "MAOIs", "SNRIs", "Atypical Antidepressants"]', 2, 'Block 1 — Q33. Explanation: MAOIs prevent breakdown of tyramine.', 33),
    (v_micro_id, 'Which virus is associated with Kaposi sarcoma in HIV/AIDS patients?', '["EBV", "HHV-6", "HHV-8", "HPV", "CMV"]', 2, 'Block 1 — Q34. Explanation: HHV-8 causes Kaposi sarcoma.', 34),
    (v_pharm_id, 'Which drug is a leukotriene receptor antagonist used in the maintenance treatment of asthma?', '["Albuterol", "Theophylline", "Montelukast", "Ipratropium", "Cromolyn"]', 2, 'Block 1 — Q35. Explanation: Montelukast blocks the CysLT1 receptor.', 35),
    (v_micro_id, 'A 60-year-old male develops diarrhea after a course of Clindamycin. Toxins A and B are detected in the stool. What is the treatment of choice?', '["Metronidazole", "Oral Vancomycin", "Ciprofloxacin", "Amoxicillin", "Doxycycline"]', 1, 'Block 1 — Q36. Explanation: C. difficile is treated with oral vancomycin or fidaxomicin.', 36),
    (v_pharm_id, 'Which drug is a sodium channel blocker (Class IA antiarrhythmic) that can cause a cinchona-like syndrome (tinnitus, headache)?', '["Lidocaine", "Quinidine", "Amiodarone", "Verapamil", "Digoxin"]', 1, 'Block 1 — Q37. Explanation: Quinidine causes cinchonism.', 37),
    (v_micro_id, 'A 10-year-old boy develops "slapped cheek" rash on his face after a mild fever. What is the causative agent?', '["Measles virus", "Rubella virus", "Parvovirus B19", "HHV-6", "Varicella-Zoster virus"]', 2, 'Block 1 — Q38. Explanation: Erythema infectiosum is caused by Parvovirus B19.', 38),
    (v_pharm_id, 'Which medication is an H2-receptor antagonist used to reduce gastric acid secretion?', '["Omeprazole", "Ranitidine", "Sucralfate", "Misoprostol", "Aluminum Hydroxide"]', 1, 'Block 1 — Q39. Explanation: Ranitidine (and Famotidine) are H2 blockers.', 39),
    (v_micro_id, 'A researcher is studying an organism that is obligate intracellular, gram-negative, and causes a rash that starts on the wrists and ankles and spreads centrally. What is the organism?', '["Rickettsia rickettsii", "Borrelia burgdorferi", "Coxiella burnetii", "Ehrlichia chaffeensis", "Treponema pallidum"]', 0, 'Block 1 — Q40. Explanation: Rocky Mountain Spotted Fever is caused by R. rickettsii.', 40),
    (v_physio_id, 'Which of the following increases the filtration fraction (FF)?', '["Constriction of afferent arteriole", "Constriction of efferent arteriole", "Obstruction of ureter", "Decreased plasma protein concentration", "Decreased renal blood flow"]', 1, 'Block 2 — Q41. Explanation: Efferent arteriole constriction increases GFR and decreases RPF, thus increasing FF.', 41),
    (v_path_id, 'A 65-year-old male with a history of smoking presents with a painless hematuria. Cytoscopy shows a mass in the bladder. What is the most likely pathological diagnosis?', '["Squamous cell carcinoma", "Primary adenocarcinoma", "Urothelial (Transitional cell) carcinoma", "Sarcoma", "Tuberculosis of bladder"]', 2, 'Block 2 — Q42. Explanation: Urothelial carcinoma is the most common bladder cancer.', 42),
    (v_physio_id, 'In the cardiac cycle, which phase immediately follows the closure of the mitral valve?', '["Isovolumetric relaxation", "Isovolumetric contraction", "Ventricular ejection", "Passive ventricular filling", "Atrial systole"]', 1, 'Block 2 — Q43. Explanation: Isovolumetric contraction occurs after the AV valves close.', 43),
    (v_path_id, 'A 50-year-old female presents with a "butterfly rash" on her face, joint pain, and proteinuria. Lab tests show positive anti-dsDNA antibodies. What is the diagnosis?', '["Rheumatoid arthritis", "Scleroderma", "Systemic Lupus Erythematosus (SLE)", "Dermatomyositis", "Sjogren syndrome"]', 2, 'Block 2 — Q44. Explanation: Anti-dsDNA is specific for SLE.', 44),
    (v_physio_id, 'Which hormone is responsible for the stimulation of bicarbonate secretion from the pancreatic ductal cells?', '["Gastrin", "Cholecystokinin (CCK)", "Secretin", "Somatostatin", "Motilin"]', 2, 'Block 2 — Q45. Explanation: Secretin stimulates bicarbonate secretion.', 45),
    (v_path_id, 'A 70-year-old male presents with weight loss and "clay-colored" stools. Physical exam shows a palpable, non-tender gallbladder (Courvoisier sign). Where is the most likely location of the tumor?', '["Tail of pancreas", "Body of pancreas", "Head of pancreas", "Gallbladder fundus", "Common bile duct"]', 2, 'Block 2 — Q46. Explanation: Pancreatic head tumors obstruct the common bile duct.', 46),
    (v_physio_id, 'In the respiratory system, what is the primary determinant of airway resistance?', '["Tracheal diameter", "Radius of the medium-sized bronchi", "Length of the conducting zone", "Viscosity of inspired air", "Surface tension of alveoli"]', 1, 'Block 2 — Q47. Explanation: Medium-sized bronchi contribute most to resistance.', 47),
    (v_path_id, 'A 15-year-old boy presents with localized bone pain. X-ray shows a "sunburst" pattern and Codman''s triangle in the distal femur. What is the diagnosis?', '["Osteoma", "Osteosarcoma", "Ewing sarcoma", "Osteochondroma", "Gaint cell tumor"]', 1, 'Block 2 — Q48. Explanation: Osteosarcoma has the sunburst pattern and Codman triangle.', 48),
    (v_physio_id, 'Which of the following occurs during the skeletal muscle contraction cycle immediately after ATP binds to myosin?', '["Myosin head pivots (power stroke)", "Myosin head detaches from actin", "Tropomyosin moves to uncover binding sites", "Calcium is released from sarcoplasmic reticulum", "Cross-bridge forms"]', 1, 'Block 2 — Q49. Explanation: ATP binding causes myosin to release actin.', 49),
    (v_path_id, 'A 55-year-old male smoker with a 40 pack-year history presents with persistent cough and hemoptysis. A biopsy of a hilar mass shows keratin pearls and intercellular bridges. What is the diagnosis?', '["Small cell carcinoma", "Adenocarcinoma", "Squamous cell carcinoma", "Large cell carcinoma", "Bronchioloalveolar carcinoma"]', 2, 'Block 2 — Q squ50. Explanation: Keratin pearls are characteristic of Squamous Cell Carcinoma.', 50),
    (v_physio_id, 'What is the primary mechanism of absorption of glucose in the small intestine?', '["Simple diffusion", "Facilitated diffusion", "Secondary active transport (SGLT1)", "Primary active transport", "Endocytosis"]', 2, 'Block 2 — Q51. Explanation: Glucose is absorbed with Na+ via SGLT1.', 51),
    (v_path_id, 'A 30-year-old female presents with tremors, heat intolerance, and exophthalmos. Lab results show low TSH and high T4. What is the most likely underlying pathology?', '["Hashimoto thyroiditis", "De Quervain thyroiditis", "Graves disease", "Toxic multinodular goiter", "TSH-secreting pituitary adenoma"]', 2, 'Block 2 — Q52. Explanation: Graves disease is characterized by hyperthyroidism and exophthalmos.', 52),
    (v_physio_id, 'Which of the following lung volumes or capacities cannot be measured by simple spirometry?', '["Vital capacity", "Inspiratory reserve volume", "Tidal volume", "Functional residual capacity", "Expiratory reserve volume"]', 3, 'Block 2 — Q53. Explanation: FRC, RV, and TLC require helium dilution or body plethysmography.', 53),
    (v_path_id, 'A 45-year-old male with chronic alcoholism presents with hematemesis. Endoscopy shows dilated veins in the distal esophagus. What is the most likely cause?', '["Peptic ulcer disease", "Mallory-Weiss tear", "Esophageal varices", "Esophagitis", "Esophageal cancer"]', 2, 'Block 2 — Q54. Explanation: Portal hypertension leads to esophageal varices.', 54),
    (v_physio_id, 'Which of the following factors shifts the hemoglobin-oxygen dissociation curve to the right?', '["Decreased temperature", "Decreased PCO2", "Increased 2,3-BPG", "Increased pH", "Carbon monoxide poisoning"]', 2, 'Block 2 — Q55. Explanation: Increased 2,3-BPG, CO2, Temp, and H+ shift the curve right (Bohr effect).', 55),
    (v_path_id, 'A 60-year-old male presents with sudden onset of "worst headache of my life." CT scan shows blood in the subarachnoid space. What is the most likely cause?', '["Middle meningeal artery rupture", "Bridging vein rupture", "Berry aneurysm rupture", "Hypertensive hemorrhage", "Arteriovenous malformation"]', 2, 'Block 2 — Q56. Explanation: Subarachnoid hemorrhage is often due to Berry aneurysm rupture.', 56),
    (v_physio_id, 'What is the effect of aldosterone on the distal tubule and collecting duct?', '["Increase Na+ reabsorption and K+ secretion", "Decrease Na+ reabsorption and K+ secretion", "Increase water reabsorption only", "Increase Na+ and K+ reabsorption", "Decrease Na+ and K+ secretion"]', 0, 'Block 2 — Q57. Explanation: Aldosterone acts on principal cells to reabsorb Na+ and secrete K+.', 57),
    (v_path_id, 'A 40-year-old male presents with mid-epigastric pain that improves with eating. Endoscopy reveals a 1cm ulcer in the first part of the duodenum. What is the most likely risk factor?', '["Chronic NSAID use", "Smoking", "Alcohol use", "Helicobacter pylori infection", "Zollinger-Ellison syndrome"]', 3, 'Block 2 — Q58. Explanation: H. pylori is the leading cause of duodenal ulcers.', 58),
    (v_physio_id, 'Which of the following receptors is responsible for the detection of linear acceleration in the horizontal plane?', '["Semicircular canals", "Utricle", "Saccule", "Cochlea", "Cupula"]', 1, 'Block 2 — Q59. Explanation: The utricle detects horizontal acceleration.', 59),
    (v_path_id, 'A biopsy from a patient with Crohn''s disease is most likely to show which of the following?', '["Crypt abscesses", "Non-caseating granulomas", "Continuous mucosal involvement", "Pseudo-polyps", "Loss of haustra"]', 1, 'Block 2 — Q60. Explanation: Non-caseating granulomas are found in Crohn''s, not Ulcerative Colitis.', 60),

    (v_path_id, 'A 28-year-old female presents with a painless, enlarged lymph node in her neck. Biopsy shows large cells with lobulated nuclei and prominent nucleoli (Reed-Sternberg cells). What is the diagnosis?', '["Follicular lymphoma", "Burkitt lymphoma", "Hodgkin lymphoma", "Diffuse large B-cell lymphoma", "Mantel cell lymphoma"]', 2, 'Block 2 — Q61. Hodgkin lymphoma is characterized by Reed-Sternberg cells.', 61),
    (v_physio_id, 'Which component of the nephron is the primary site of action for Thiazide diuretics?', '["Proximal convoluted tubule", "Thick ascending limb", "Distal convoluted tubule", "Collecting duct", "Descending limb"]', 2, 'Block 2 — Q62. Thiazides inhibit the Na/Cl symporter in the DCT.', 62),
    (v_path_id, 'A 45-year-old male presents with sudden onset of severe pain and swelling in his left great toe. Joint aspiration shows needle-shaped, negatively birefringent crystals. What is the diagnosis?', '["Pseudogout", "Rheumatoid arthritis", "Gout", "Septic arthritis", "Osteoarthritis"]', 2, 'Block 2 — Q63. Gout is caused by monosodium urate crystals.', 63),
    (v_physio_id, 'Which of the following increases myocardial contractility (inotropy)?', '["Beta-1 adrenergic stimulation", "Vagal stimulation", "Beta-blockers", "Hyperkalemia", "Increased afterload"]', 0, 'Block 2 — Q64. Beta-1 activation increases cAMP and intracellular Calcium.', 64),
    (v_path_id, 'A 60-year-old male with long-standing GERD undergoes endoscopy. Biopsy of the distal esophagus shows specialized columnar epithelium with goblet cells. What is this condition called?', '["Esophagitis", "Barrett esophagus", "Esophageal varices", "Squamous dysplasia", "Achalasia"]', 1, 'Block 2 — Q65. Barrett esophagus is intestinal metaplasia due to chronic acid reflux.', 65),
    (v_physio_id, 'What is the primary stimulus for the release of erythropoietin (EPO)?', '["Hypoxia", "Hypercapnia", "Anemia", "High altitude", "Low blood pressure"]', 0, 'Block 2 — Q66. Renal peritubular interstitial cells release EPO in response to low O2.', 66),
    (v_path_id, 'A 70-year-old male presents with prostatic enlargement and difficulty urinating. Biopsy shows hyperplasia of glandular and stromal elements. Which hormone is primarily responsible?', '["Testosterone", "Dihydrotestosterone (DHT)", "Estrogen", "LH", "FSH"]', 1, 'Block 2 — Q67. DHT, produced via 5-alpha reductase, drives BPH.', 67),
    (v_physio_id, 'Which of the following describes the effect of a right-to-left shunt on arterial blood gases?', '["Decreased PaO2", "Increased PaO2", "Decreased PaCO2", "Increased SaO2", "Decreased pH"]', 0, 'Block 2 — Q68. R-to-L shunts bypass the lungs, leading to hypoxemia.', 68),
    (v_path_id, 'Which type of lung cancer occurs centrally and is strongly associated with a paraneoplastic syndrome of SIADH or ACTH production?', '["Adenocarcinoma", "Squamous cell carcinoma", "Small cell carcinoma", "Large cell carcinoma", "Carcinoid tumor"]', 2, 'Block 2 — Q69. Small cell carcinoma is a neuroendocrine tumor.', 69),
    (v_physio_id, 'The majority of CO2 in the blood is transported in which form?', '["Dissolved CO2", "Carbaminohemoglobin", "Bicarbonate (HCO3-)", "Carbonic acid", "Carbonate"]', 2, 'Block 2 — Q70. 70% of CO2 is transported as bicarbonate.', 70),
    (v_path_id, 'A 50-year-old male presents with crushing chest pain. EKG shows ST-elevation in leads V1-V4. Which coronary artery is most likely occluded?', '["Right coronary artery", "Left circumflex artery", "Left anterior descending artery (LAD)", "Left main artery", "Posterior descending artery"]', 2, 'Block 2 — Q71. LAD supply the anterior wall of the heart.', 71),
    (v_physio_id, 'Which of the following increases the p50 of the oxygen-hemoglobin dissociation curve?', '["Increased pH", "Decreased PCO2", "Increased 2,3-BPG", "Decreased temperature", "Carbon monoxide"]', 2, 'Block 2 — Q72. Right shift (increased p50) is caused by increased 2,3-BPG, H+, CO2, Temp.', 72),
    (v_path_id, 'A 35-year-old female presents with a "cold" thyroid nodule. Histology shows psammoma bodies and orphan annie eye nuclei. What is the diagnosis?', '["Follicular carcinoma", "Medullary carcinoma", "Papillary carcinoma", "Anaplastic carcinoma", "Hurthle cell tumor"]', 2, 'Block 2 — Q73. Papillary carcinoma is the most common thyroid cancer.', 73),
    (v_physio_id, 'What is the role of bile salts in digestion?', '["Protein breakdown", "Micelle formation and fat emulsification", "Carbohydrate absorption", "Vitamin B12 absorption", "Neutralizing stomach acid"]', 1, 'Block 2 — Q74. Bile salts emulsify fats to increase surface area for lipase.', 74),
    (v_path_id, 'A patient presents with bloody diarrhea and abdominal pain. Colonoscopy shows continuous mucosal inflammation starting from the rectum. What is the diagnosis?', '["Crohn disease", "Ulcerative colitis", "Ischemic colitis", "Infectious colitis", "Diverticulitis"]', 1, 'Block 2 — Q75. UC is continuous and involves the rectum.', 75),
    (v_physio_id, 'Which hormone inhibits gastric acid secretion and gallbladder contraction?', '["Gastrin", "Secretin", "Somatostatin", "Cholecystokinin (CCK)", "Motilin"]', 2, 'Block 2 — Q76. Somatostatin is the universal inhibitory hormone.', 76),
    (v_path_id, 'A 60-year-old male smoker has hematuria and a flank mass. Histology shows cells with abundant clear cytoplasm. What is the diagnosis?', '["Urothelial carcinoma", "Renal cell carcinoma (Clear cell)", "Wilms tumor", "Angiomyolipoma", "Oncocytoma"]', 1, 'Block 2 — Q77. RCC is associated with VHL gene mutations.', 77),
    (v_physio_id, 'What happens to the lung compliance in a patient with pulmonary fibrosis?', '["Increases", "Decreases", "Stays the same", "Becomes negative", "Doubles"]', 1, 'Block 2 — Q78. Fibrosis increases lung elastic recoil, decreasing compliance.', 78),
    (v_path_id, 'Which valvular lesion is characterized by a mid-systolic click followed by a late systolic murmur?', '["Aortic stenosis", "Mitral regurgitation", "Mitral valve prolapse", "Aortic regurgitation", "Mitral stenosis"]', 2, 'Block 2 — Q79. MVP is caused by myxomatous degeneration of the valve leaflets.', 79),
    (v_physio_id, 'Which of the following is the primary mediator of the myogenic response in renal autoregulation?', '["Nitric oxide", "Stretch-activated ion channels", "Angiotensin II", "Prostacyclin", "Endothelin"]', 1, 'Block 2 — Q80. Increased pressure stretches the arteriole, causing reflex contraction.', 80),

    -- 5. Insert BLOCK 3 (Biochem & Genetics: Q81-120)
    (v_biochem_id, 'A 1-year-old boy presents with intellectual disability, a "musty" body odor, and fair skin. Which enzyme is most likely deficient?', '["Tyrosinase", "Phenylalanine hydroxylase", "Homogentisate oxidase", "Cystathionine synthase", "Branched-chain alpha-keto acid dehydrogenase"]', 1, 'Block 3 — Q81. Phenylketonuria (PKU) is caused by PAH deficiency.', 81),
    (v_biochem_id, 'A patient presents with painful muscle cramps during exercise. Blood lactate levels do not rise after an ischemic forearm test. What is the diagnosis?', '["Von Gierke disease", "Pompe disease", "Cori disease", "McArdle disease", "Anderson disease"]', 3, 'Block 3 — Q82. McArdle disease is a skeletal muscle glycogen phosphorylase deficiency.', 82),
    (v_genetics_id, 'A 4-year-old boy with intellectual disability has large ears and a prominent jaw. Genetic testing shows an increased number of CGG repeats. What is the diagnosis?', '["Down syndrome", "Fragile X syndrome", "Patau syndrome", "Edwards syndrome", "Klinefelter syndrome"]', 1, 'Block 3 — Q83. Fragile X is caused by CGG repeats in the FMR1 gene.', 83),
    (v_biochem_id, 'Which vitamin deficiency leads to scurvy, characterized by easy bruising, petechiae, and "corkscrew" hairs?', '["Vitamin A", "Vitamin C", "Vitamin D", "Vitamin K", "Vitamin B1"]', 1, 'Block 3 — Q84. Vitamin C is needed for collagen hydroxylation.', 84),
    (v_biochem_id, 'A 30-year-old male with a history of recurrent kidney stones passes a stone that is hexagonal and "envelope-shaped" crystals. Which amino acid transporter is likely defective?', '["Cystine/Ornithine/Lysine/Arginine (COLA)", "Tryptophan", "Phenylalanine", "Tyrosine", "Leucine"]', 0, 'Block 3 — Q85. Cystinuria is caused by defective COLA transporter.', 85),
    (v_genetics_id, 'Which mode of inheritance is characterized by all daughters of an affected father being affected, but none of the sons being affected?', '["Autosomal dominant", "Autosomal recessive", "X-linked dominant", "X-linked recessive", "Mitochondrial"]', 2, 'Block 3 — Q86. X-linked dominant inheritance pattern.', 86),
    (v_biochem_id, 'Which enzyme is the rate-limiting step of glycolysis?', '["Hexokinase", "Phosphofructokinase-1 (PFK-1)", "Pyruvate kinase", "Glucose-6-phosphatase", "Aldolase"]', 1, 'Block 3 — Q87. PFK-1 is the primary rate-limiting enzyme of glycolysis.', 87),
    (v_biochem_id, 'A 2-year-old boy with coarse facial features and hepatosplenomegaly is diagnosed with Hunter syndrome. Which enzyme is deficient?', '["Alpha-L-iduronidase", "Iduronate sulfatase", "Beta-glucosidase", "Galactocerebrosidase", "Sphingomyelinase"]', 1, 'Block 3 — Q88. Hunter syndrome (X-linked) is iduronate sulfatase deficiency.', 88),
    (v_genetics_id, 'A patient with Marfan syndrome has a mutation in which gene?', '["FBN1", "COL1A1", "COL3A1", "NF1", "NF2"]', 0, 'Block 3 — Q89. Marfan syndrome is caused by Fibrillin-1 (FBN1) mutations.', 89),
    (v_biochem_id, 'Which process occurs in the mitochondria?', '["Glycolysis", "Fatty acid synthesis", "TCA cycle", "Cholesterol synthesis (partially)", "Pentose phosphate pathway"]', 2, 'Block 3 — Q90. TCA cycle and Beta-oxidation occur in the mitochondria.', 90),
    (v_biochem_id, 'A 35-year-old male presents with dark urine on standing and ochronosis (blue-black pigmentation of cartilage). Which enzyme is deficient?', '["Tyrosinase", "Homogentisate oxidase", "Phenylalanine hydroxylase", "Cystathionine synthase", "Uroporphyrinogen decarboxylase"]', 1, 'Block 3 — Q91. Alkaptonuria is homogensitate oxidase deficiency.', 91),
    (v_genetics_id, 'Cystic Fibrosis is most commonly caused by a deletion of which amino acid at position 508?', '["Valine", "Phenylalanine", "Leucine", "Isoleucine", "Glycine"]', 1, 'Block 3 — Q92. delta-F508 is the common CFTR mutation.', 92),
    (v_biochem_id, 'Which metabolic pathway produces NADPH for reductive biosynthesis and ribose-5-phosphate for nucleotide synthesis?', '["Glycolysis", "Gluconeogenesis", "Pentose phosphate pathway (PPP)", "Beta-oxidation", "Urea cycle"]', 2, 'Block 3 — Q93. PPP (HMP shunt) is the source of NADPH.', 93),
    (v_biochem_id, 'What is the rate-limiting enzyme of the urea cycle?', '["Carbamoyl phosphate synthetase I", "Ornithine transcarbamylase", "Argininosuccinate synthase", "Arginase", "Glutamine synthetase"]', 0, 'Block 3 — Q94. CPS-I is the rate-limiting step in urea cycle.', 94),
    (v_genetics_id, 'A child presents with a "cat-like" cry, intellectual disability, and microcephaly. What is the chromosomal abnormality?', '["Trisomy 21", "Trisomy 18", "Deletion of 5p", "Deletion of 4p", "Klinefelter syndrome"]', 2, 'Block 3 — Q95. Cri-du-chat syndrome is 5p deletion.', 95),
    (v_biochem_id, 'A patient with "Wernicke-Korsakoff syndrome" is deficient in which vitamin?', '["B1 (Thiamine)", "B2 (Riboflavin)", "B3 (Niacin)", "B6 (Pyridoxine)", "C"]', 0, 'Block 3 — Q96. Thiamine deficiency is common in alcoholics.', 96),
    (v_biochem_id, 'Which vitamin is a cofactor for decarboxylation reactions, like the conversion of pyruvate to acetyl-CoA?', '["B1", "B2", "B3", "B5", "B6"]', 0, 'Block 3 — Q97. B1 (TPP) is a cofactor for pyruvate dehydrogenase.', 97),
    (v_genetics_id, 'A 30-year-old woman with a history of recurrent miscarriages is found to have a Robertsonian translocation. This involves which of the following chromosomes?', '["13, 14, 15, 21, 22", "1, 2, 3, 4, 5", "X and Y", "6 and 11", "9 and 22"]', 0, 'Block 3 — Q98. Robertsonian translocations involve acrocentric chromosomes.', 98),
    (v_biochem_id, 'Which pathway is responsible for creating glucose from non-carbohydrate precursors like lactate and glycerol?', '["Glycolysis", "Gluconeogenesis", "Glycogenolysis", "Lipolysis", "Ketogenesis"]', 1, 'Block 3 — Q99. Gluconeogenesis occurs during fasting.', 99),
    (v_biochem_id, 'The "Rate-limiting step" of the Pentose Phosphate Pathway is catalyzed by which enzyme?', '["Glucose-6-phosphate dehydrogenase (G6PD)", "Transketolase", "Phosphoglucomutase", "6-phosphogluconolactone", "Ribulose-5-phosphate"]', 0, 'Block 3 — Q100. G6PD is the rate-limiting enzyme.', 100),
    (v_biochem_id, 'A 2-day-old infant develops jaundice. Lab results show elevated indirect bilirubin. What is the most likely cause?', '["Biliary atresia", "Gilbert syndrome", "Physiological jaundice of the newborn", "Crigler-Najjar syndrome", "Dubin-Johnson syndrome"]', 2, 'Block 3 — Q101. Neonatal jaundice is due to immature UDP-glucuronosyltransferase.', 101),
    (v_biochem_id, 'Which vitamin is essential for the synthesis of visual pigments and differentiation of epithelial cells?', '["Vitamin A", "Vitamin D", "Vitamin E", "Vitamin K", "Vitamin B12"]', 0, 'Block 3 — Q102. Vitamin A (Retinol) is critical for vision.', 102),
    (v_genetics_id, 'Which genetic disorder is characterized by a mutation in the NF1 gene on chromosome 17?', '["Neurofibromatosis type 1", "Neurofibromatosis type 2", "Tuberous sclerosis", "Von Hippel-Lindau disease", "Sturge-Weber syndrome"]', 0, 'Block 3 — Q103. NF1 (von Recklinghausen disease) has Cafe-au-lait spots.', 103),
    (v_biochem_id, 'The absence of which enzyme leads to Lesch-Nyhan syndrome, characterized by gout and self-mutilation?', '["Adenosine deaminase", "HGPRT", "Xanthine oxidase", "PRPP synthetase", "Urate oxidase"]', 1, 'Block 3 — Q104. HGPRT deficiency leads to hyperuricemia.', 104),
    (v_biochem_id, 'Which of the following is the rate-limiting enzyme of the citric acid cycle?', '["Citrate synthase", "Isocitrate dehydrogenase", "Alpha-ketoglutarate dehydrogenase", "Succinate dehydrogenase", "Malate dehydrogenase"]', 1, 'Block 3 — Q105. Isocitrate dehydrogenase is the main regulatory step.', 105),
    (v_biochem_id, 'A patient with chronic alcoholism presents with "casal necklace" rash, diarrhea, and dementia. Which vitamin is deficient?', '["B1", "B2", "B3 (Niacin)", "B6", "B12"]', 2, 'Block 3 — Q106. Pellagra (3 Ds) is caused by Niacin deficiency.', 106),
    (v_genetics_id, 'Maternal inheritance of a deletion on chromosome 15q11-q13 results in which syndrome?', '["Prader-Willi syndrome", "Angelman syndrome", "Down syndrome", "Turner syndrome", "DiGeorge syndrome"]', 1, 'Block 3 — Q107. Angelman syndrome results from maternal deletion; Prader-Willi from paternal.', 107),
    (v_biochem_id, 'Which enzyme converts glucose to glucose-6-phosphate in the liver and has a high Km for glucose?', '["Hexokinase", "Glucokinase", "Phosphofructokinase", "Pyruvate kinase", "Glucose phosphatase"]', 1, 'Block 3 — Q108. Glucokinase acts as a glucose sensor in the liver.', 108),
    (v_genetics_id, 'What is the characteristic chromosomal finding in a patient with Turner syndrome?', '["47,XXY", "45,X", "47,XY,+21", "47,XXX", "46,XY"]', 1, 'Block 3 — Q109. Turner syndrome is a monosomy X.', 109),
    (v_biochem_id, 'Which metabolic pathway occurs entirely in the cytosol?', '["TCA cycle", "Beta-oxidation", "Fatty acid synthesis", "Ketogenesis", "Electron transport chain"]', 2, 'Block 3 — Q110. Fatty acid synthesis occurs in the cytosol.', 110),
    (v_biochem_id, 'A 6-month-old boy with developmental delay and a "startle response" to noise is found to have a "cherry-red spot" on the macula. Which enzyme is deficient?', '["Hexosaminidase A", "Sphingomyelinase", "Beta-galactosidase", "Glucocerebrosidase", "Iduronate sulfatase"]', 0, 'Block 3 — Q111. Tay-Sachs disease is hexosaminidase A deficiency.', 111),
    (v_biochem_id, 'Which amino acid is the precursor for Serotonin, Melatonin, and Niacin?', '["Tyrosine", "Tryptophan", "Phenylalanine", "Histidine", "Arginine"]', 1, 'Block 3 — Q112. Tryptophan is the starting point for these molecules.', 112),
    (v_genetics_id, 'Which genetic principle explains why a patient with a disease genotype may not show the disease phenotype?', '["Pleiotropy", "Variable expressivity", "Incomplete penetrance", "Anticipation", "Mosaicism"]', 2, 'Block 3 — Q113. Penetrance is the percentage of individuals with a genotype who show the phenotype.', 113),
    (v_biochem_id, 'What is the rate-limiting enzyme of fatty acid oxidation (beta-oxidation)?', '["Acetyl-CoA carboxylase", "Carnitine acyltransferase I (CAT-I)", "HMG-CoA reductase", "Lipoprotein lipase", "Carnitine acyltransferase II"]', 1, 'Block 3 — Q114. CAT-I (CPT-1) controls fatty acid entry into mitochondria.', 114),
    (v_biochem_id, 'Which mineral is a key component of Vitamin B12?', '["Iron", "Magnesium", "Cobalt", "Zinc", "Copper"]', 2, 'Block 3 — Q115. Vitamin B12 is also known as Cobalamin.', 115),
    (v_biochem_id, 'Deficiency of which enzyme leads to "Maple Syrup Urine Disease"?', '["Phenylalanine hydroxylase", "Tyrosinase", "Branched-chain alpha-ketoacid dehydrogenase", "Propionyl-CoA carboxylase", "Methylmalonyl-CoA mutase"]', 2, 'Block 3 — Q116. MSUD leads to accumulation of Leucine, Isoleucine, and Valine.', 116),
    (v_genetics_id, 'What is the karyotype of a male with Klinefelter syndrome?', '["45,X", "47,XXY", "47,XYY", "46,XX", "47,XXX"]', 1, 'Block 3 — Q117. Klinefelter is characterized by an extra X chromosome.', 117),
    (v_biochem_id, 'Which glucose transporter is insulin-dependent and found in adipose tissue and skeletal muscle?', '["GLUT1", "GLUT2", "GLUT3", "GLUT4", "GLUT5"]', 3, 'Block 3 — Q118. GLUT4 is sequestered in vesicles and moved to the membrane by insulin.', 118),
    (v_biochem_id, 'A patient with "night blindness" and dry skin is likely deficient in which vitamin?', '["Vitamin A", "Vitamin C", "Vitamin D", "Vitamin E", "Vitamin K"]', 0, 'Block 3 — Q119. Vitamin A is essential for retinal function.', 119),
    (v_biochem_id, 'Which enzyme is inhibited by lead, resulting in anemia and "basophilic stippling"?', '["Ferrochelatase", "ALA dehydratase", "Uroporphyrinogen decarboxylase", "Heme oxygenase", "Bilirubin reductase"]', 1, 'Block 3 — Q120. Lead inhibits ALA dehydratase and ferrochelatase.', 120),
    (v_beh_id, 'A 30-year-old female believes her neighbors are spying on her with hidden cameras despite no evidence. This symptom is best described as a:', '["Hallucination", "Delusion", "Illusion", "Loosening of association", "Flat affect"]', 1, 'Block 4 — Q121. Delusion is a fixed false belief.', 121),
    (v_biostat_id, 'A study is conducted to compare the incidence of lung cancer in smokers vs. non-smokers. What is the appropriate measure of association?', '["Odds ratio", "Relative risk", "Prevalence", "Case fatality rate", "Standard deviation"]', 1, 'Block 4 — Q122. Relative Risk is used for cohort studies (incidence).', 122),
    (v_beh_id, 'An 8-year-old boy is brought in for difficulty paying attention, impulsivity, and constant movement. What is the most likely diagnosis?', '["Autism spectrum disorder", "Attention-deficit/hyperactivity disorder (ADHD)", "Conduct disorder", "Oppositional defiant disorder", "Tourette syndrome"]', 1, 'Block 4 — Q123. ADHD is characterized by inattention and hyperactivity.', 123),
    (v_biostat_id, 'What is the "Power" of a statistical test defined as?', '["1 - Type I error (alpha)", "1 - Type II error (beta)", "The p-value", "The confidence interval", "The effect size"]', 1, 'Block 4 — Q124. Power (1-beta) is the ability to detect a true difference.', 124),
    (v_beh_id, 'A patient who is angry with their spouse begins to yell at their dog. This is an example of which defense mechanism?', '["Projection", "Reaction formation", "Displacement", "Sublimation", "Rationalization"]', 2, 'Block 4 — Q125. Displacement redirects emotions to a safer target.', 125),
    (v_biostat_id, 'A new diagnostic test has a sensitivity of 90% and a specificity of 80%. If the prevalence of the disease increases, what happens to the Positive Predictive Value (PPV)?', '["Increases", "Decreases", "Stays the same", "Becomes zero", "Impossible to tell"]', 0, 'Block 4 — Q126. PPV is directly proportional to prevalence.', 126),
    (v_beh_id, 'A 70-year-old woman is brought in with progressive memory loss and disorientation. She can no longer perform activities of daily living. Pathological findings likely include Beta-amyloid plaques. What is the diagnosis?', '["Wernicke encephalopathy", "Vascular dementia", "Alzheimer disease", "Lewy body dementia", "Frontotemporal dementia"]', 2, 'Block 4 — Q127. Alzheimer disease is characterized by plaques and tangles.', 127),
    (v_biostat_id, 'Which type of study design looks at a group of people with a disease and compares them to those without to find past exposures?', '["Cohort study", "Case-control study", "Cross-sectional study", "Randomized controlled trial", "Meta-analysis"]', 1, 'Block 4 — Q128. Case-control studies are retrospective.', 128),
    (v_beh_id, 'A patient presents with weight loss, binge eating, and compensatory behaviors like vomiting. What is the diagnosis?', '["Anorexia nervosa", "Bulimia nervosa", "Binge-eating disorder", "Avoidant/restrictive food intake disorder", "Pica"]', 1, 'Block 4 — Q129. Bulimia involves purging; Anorexia is low BMI.', 129),
    (v_biostat_id, 'The "Odds Ratio" is typically calculated for which type of study?', '["Cohort", "Case-control", "Cross-sectional", "Clinical Trial", "Descriptive"]', 1, 'Block 4 — Q130. OR is the main measure for case-control studies.', 130),
    (v_beh_id, 'Common side effects of SSRIs include which of the following?', '["Hypertensive crisis", "Weight loss only", "Sexual dysfunction", "Urinary retention", "Tinnitus"]', 2, 'Block 4 — Q131. Sexual dysfunction and GI upset are common with SSRIs.', 131),
    (v_biostat_id, 'If a test is "Reliable", it means that the test is:', '["Accurate", "Reproducible", "Specific", "Sensitive", "High power"]', 1, 'Block 4 — Q132. Reliability equals consistency/reproducibility.', 132),
    (v_beh_id, 'A 25-year-old male with a history of arson and animal cruelty shows no remorse and violates the rights of others. What is the most likely diagnosis?', '["Schizotypal personality disorder", "Antisocial personality disorder", "Borderline personality disorder", "Narcissistic personality disorder", "Histrionic personality disorder"]', 1, 'Block 4 — Q133. Antisocial PD (conduct disorder if <18).', 133),
    (v_biostat_id, 'A "Type I error" occurs when:', '["The null hypothesis is rejected when it is true", "The null hypothesis is accepted when it is false", "The sample size is too small", "The p-value is greater than 0.05", "The confidence interval includes 1"]', 0, 'Block 4 — Q134. Type I (Alpha) error is a "false positive" in testing.', 134),
    (v_beh_id, 'A patient who has just been diagnosed with terminal cancer says, "The doctors must have the wrong charts." Which stage of grief is this?', '["Anger", "Bargaining", "Depression", "Acceptance", "Denial"]', 4, 'Block 4 — Q135. Dabda: Denial, Anger, Bargaining, Depression, Acceptance.', 135),
    (v_biostat_id, 'What happens to the confidence interval if the sample size is increased?', '["Narrows", "Widens", "Stays the same", "Disappears", "Becomes negative"]', 0, 'Block 4 — Q136. Larger N reduces standard error, narrowing the CI.', 136),
    (v_beh_id, 'A 19-year-old student has a fear of speaking in public and avoids it at all costs. What is the diagnosis?', '["Generalized anxiety disorder", "Social anxiety disorder", "Agoraphobia", "Panic disorder", "Specific phobia"]', 1, 'Block 4 — Q137. Social anxiety is fear of scrutiny/humiliation.', 137),
    (v_biostat_id, 'Which value is the most affected by "outliers" in a data set?', '["Median", "Mode", "Mean", "Standard deviation", "Quartile"]', 2, 'Block 4 — Q138. The mean is sensitive to extreme values.', 138),
    (v_beh_id, 'The mechanism of action of typical antipsychotics (like Haloperidol) primarily involves blocking which receptor?', '["Serotonin 5-HT2", "Norepinephrine Alpha-1", "Dopamine D2", "Muscarinic M1", "Histamine H1"]', 2, 'Block 4 — Q139. D2 blockade is the main effect of typicals.', 139),
    (v_biostat_id, 'A p-value of 0.01 means:', '["There is a 1% chance the result is due to chance", "There is a 99% chance the result is true", "The result is clinically significant", "The power is 0.99", "The null hypothesis is true"]', 0, 'Block 4 — Q140. Statistical significance probability.', 140),
    (v_beh_id, 'A patient who is in a "manic" state with decreased sleep, grandiosity, and impulsivity should be treated with which first-line medication?', '["Lithium", "Fluoxetine", "Alprazolam", "Sertraline", "Bupropion"]', 0, 'Block 4 — Q141. Lithium is a classic mood stabilizer.', 141),
    (v_beh_id, 'A 45-year-old male recently stopped drinking alcohol and is now experiencing tremors, sweating, and visual hallucinations. What is the diagnosis?', '["Schizophrenia", "Delirium tremens", "Major depression", "Panic attack", "Bipolar disorder"]', 1, 'Block 4 — Q142. DTs occur 48-96h after alcohol cessation.', 142),
    (v_biostat_id, 'Which statistical test is used to compare the means of exactly two groups?', '["Analysis of variance (ANOVA)", "T-test", "Chi-square test", "Correlation coefficient", "Z-test"]', 1, 'Block 4 — Q143. T-test compares two means.', 143),
    (v_beh_id, 'A patient who is sexually attracted to their therapist and begins to treat the therapist like their parent is an example of:', '["Countertransference", "Transference", "Splitting", "Acting out", "Idealization"]', 1, 'Block 4 — Q144. Transference is the redirection of patient feelings to the physician.', 144),
    (v_biostat_id, 'The "incidence" of a disease refers to:', '["The total number of people with the disease in a population", "The number of new cases in a population over a period of time", "The probability of dying from the disease", "The sensitivity of the screening test", "The prevalence minus the duration"]', 1, 'Block 4 — Q145. Incidence tracks new cases.', 145),
    (v_beh_id, 'Which personality disorder is characterized by a "magical thinking," strange beliefs, and social isolation?', '["Schizoid", "Schizotypal", "Paranoid", "Avoidant", "Borderline"]', 1, 'Block 4 — Q146. Schizotypal PD involves odd behavior and beliefs.', 146),
    (v_biostat_id, 'A study finds that a high intake of saturated fat is correlated with heart disease. However, the study also reveals that people who eat more fat also exercise less. Exercise here is a:', '["Confounding variable", "Bias", "Standard error", "Dependent variable", "Null hypothesis"]', 0, 'Block 4 — Q147. Confounding variables distort the relationship.', 147),
    (v_beh_id, 'A patient who presents with numerous physical complaints (pain, GI, neuro) that cannot be medically explained is most likely suffering from:', '["Conversion disorder", "Somatic symptom disorder", "Factitious disorder", "Malingering", "Illness anxiety disorder"]', 1, 'Block 4 — Q148. Somatic symptom disorder involves distressing physical symptoms.', 148),
    (v_biostat_id, 'Which measure tells you how much of the disease in a population can be attributed to a specific risk factor?', '["Relative risk", "Odds ratio", "Attributable risk", "Number needed to treat", "Incidence"]', 2, 'Block 4 — Q149. Attributable risk quantifies excess risk.', 149),
    (v_beh_id, 'What is the "First-pass effect"?', '["The excretion of a drug by the kidneys", "The metabolism of a drug by the liver after oral administration", "The distribution of a drug to the brain", "The binding of a drug to albumin", "The absorption of a drug in the stomach"]', 1, 'Block 4 — Q150. Oral drugs pass through the liver via the portal vein first.', 150),
    (v_beh_id, 'A 24-year-old woman is preoccupied with the idea that she has a serious kidney disease despite normal labs and doctor reassurance. What is the diagnosis?', '["Somatic symptom disorder", "Illness anxiety disorder", "Conversion disorder", "Factitious disorder", "Malingering"]', 1, 'Block 4 — Q151. Illness anxiety is worry about having a disease with minimal symptoms.', 151),
    (v_biostat_id, 'What is the "Sensitivity" of a test defined as?', '["TP / (TP + FN)", "TN / (TN + FP)", "TP / (TP + FP)", "TN / (TN + FN)", "1 - Specificity"]', 0, 'Block 4 — Q152. Sensitivity is the true positive rate.', 152),
    (v_beh_id, 'An infant is able to sit up without support and has a "pincer grasp." These milestones typically occur at which age?', '["2 months", "4 months", "6 months", "9 months", "12 months"]', 3, 'Block 4 — Q153. Sitting and pincer grasp are 9-month milestones.', 153),
    (v_biostat_id, 'The "Number Needed to Treat" (NNT) is calculated as:', '["1 / Absolute Risk Reduction (ARR)", "1 / Relative Risk", "ARR / Control Rate", "Sensitivity / (1 - Specificity)", "1 - Power"]', 0, 'Block 4 — Q154. NNT is the inverse of ARR.', 154),
    (v_beh_id, 'A patient who purposely fakes an illness because they want to assume the "sick role" (no external gain) has:', '["Malingering", "Factitious disorder", "Conversion disorder", "Somatic symptom disorder", "Hypochondriasis"]', 1, 'Block 4 — Q155. Factitious disorder (Munchausen) is for primary/sick role gain.', 155),
    (v_biostat_id, 'Which value is the "Middle" value in a sorted data set?', '["Mean", "Median", "Mode", "Variance", "Range"]', 1, 'Block 4 — Q156. Median is the 50th percentile.', 156),
    (v_beh_id, 'Side effects of lithium toxicity commonly include which of the following?', '["Hypertension", "Diabetes insipidus", "Hypercalcemia", "Tachycardia", "Priapism"]', 1, 'Block 4 — Q157. Lithium causes nephrogenic DI.', 157),
    (v_biostat_id, 'What is the definition of "Specificity"?', '["The probability that an unaffected person tests negative", "The probability that an affected person tests positive", "The proportion of positive tests that are true positives", "The proportion of negative tests that are true negatives", "The power of the study"]', 0, 'Block 4 — Q158. Specificity is the true negative rate.', 158),
    (v_beh_id, 'A patient with "Schizophrenia" must have symptoms for at least how many months to meet the diagnosis?', '["1 month", "3 months", "6 months", "12 months", "24 months"]', 2, 'Block 4 — Q159. Schizophrenia requires 6 months; Schizophreniform 1-6 months.', 159),
    (v_biostat_id, 'What is the "Standard Deviation"?', '["The average of all values", "A measure of the dispersion of data around the mean", "The difference between the max and min", "The square of the variance", "The p-value"]', 1, 'Block 4 — Q160. SD measures how spread out the numbers are.', 160),
    (v_anatomy_id, 'A 30-year-old male presents with "winging of the scapula" after a radical mastectomy. Which nerve was likely damaged?', '["Axillary nerve", "Long thoracic nerve", "Thoracodorsal nerve", "Radial nerve", "Median nerve"]', 1, 'Block 5 — Q161. Serratus anterior is innervated by the long thoracic nerve.', 161),
    (v_anatomy_id, 'Injury to the radial nerve at the humerus (mid-shaft) would most likely cause which of the following?', '["Claw hand", "Wrist drop", "Ape hand", "Loss of abduction", "Loss of elbow extension"]', 1, 'Block 5 — Q162. Radial nerve provides extension to the wrist.', 162),
    (v_anatomy_id, 'Which artery is the primary supplier to the femoral head, and when damaged, leads to avascular necrosis?', '["Lateral circumflex femoral artery", "Medial circumflex femoral artery", "Obturator artery", "Deep femoral artery", "Popliteal artery"]', 1, 'Block 5 — Q163. Medial circumflex femoral artery is the main supply.', 163),
    (v_anatomy_id, 'A patient cannot abduct their arm beyond 15 degrees. Which nerve and muscle are affected?', '["Musculocutaneous; Biceps", "Axillary; Deltoid", "Suprascapular; Supraspinatus", "Radial; Triceps", "Long thoracic; Serratus anterior"]', 1, 'Block 5 — Q164. Deltoid (Axillary nerve) abducts from 15 to 90 degrees.', 164),
    (v_anatomy_id, 'Fracture of the surgical neck of the humerus most commonly damages which nerve?', '["Radial nerve", "Axillary nerve", "Median nerve", "Ulnar nerve", "Musculocutaneous nerve"]', 1, 'Block 5 — Q165. Axillary nerve wraps around the surgical neck.', 165),
    (v_anatomy_id, 'Which pharyngeal arch gives rise to the muscles of facial expression?', '["First arch", "Second arch", "Third arch", "Fourth arch", "Sixth arch"]', 1, 'Block 5 — Q166. CN VII (Facial) and second arch muscles.', 166),
    (v_anatomy_id, 'A patient has a "claw hand" affecting the 4th and 5th digits. Which nerve is compressed?', '["Median nerve", "Ulnar nerve", "Radial nerve", "Axillary nerve", "Musculocutaneous nerve"]', 1, 'Block 5 — Q167. Ulnar nerve injury at the wrist results in ulnar claw.', 167),
    (v_inter_id, 'Which pharyngeal pouch gives rise to the thymus and inferior parathyroid glands?', '["First pouch", "Second pouch", "Third pouch", "Fourth pouch", "Fifth pouch"]', 2, 'Block 5 — Q168. 3rd pouch = thymus + inferior parathyroids.', 168),
    (v_anatomy_id, 'The "Brachial Plexus" is formed by the ventral rami of which spinal nerves?', '["C1-C4", "C5-T1", "T1-T12", "L1-L5", "S1-S4"]', 1, 'Block 5 — Q169. C5 to T1 forms the plexus.', 169),
    (v_inter_id, 'The failure of the neural tube to close at the caudal end results in:', '["Anencephaly", "Spina bifida", "Hirschsprung disease", "Cleft palate", "Holoprosencephaly"]', 1, 'Block 5 — Q170. Spina bifida is a caudal tube closure failure.', 170),
    (v_inter_id, 'A 4-year-old boy presents with hypocalcemic tetany and recurrent viral infections. Chest X-ray shows no thymic shadow. Which diagnosis is most likely?', '["Bruton agammaglobulinemia", "DiGeorge syndrome", "SCID", "Hyper-IgM", "Selective IgA deficiency"]', 1, 'Block 5 — Q171. 22q11 deletion fails to develop 3rd/4th pouches.', 171),
    (v_inter_id, 'Which type of hypersensitivity involves IgE-mediated Mast cell degranulation?', '["Type I", "Type II", "Type III", "Type IV", "Type V"]', 0, 'Block 5 — Q172. Type I is immediate/allergic.', 172),
    (v_inter_id, 'A "Type II" hypersensitivity reaction is characterized by:', '["Immune complex deposition", "Delayed T-cell response", "Antibody-mediated cytotoxic cell destruction", "IgE-mediated degranulation", "Granuloma formation"]', 2, 'Block 5 — Q173. Antibody binding to cell surfaces.', 173),
    (v_inter_id, 'Serum sickness and systemic lupus erythematosus (SLE) are examples of which hypersensitivity?', '["Type I", "Type II", "Type III", "Type IV", "Type V"]', 2, 'Block 5 — Q174. Type III involves immune complex deposition.', 174),
    (v_inter_id, 'MHC Class I molecules are found on:', '["All nucleated cells", "Antigen-presenting cells only", "T-cells only", "B-cells only", "Red blood cells"]', 0, 'Block 5 — Q175. MHC I presents endogenous antigens.', 175),
    (v_inter_id, 'Which cytokine is the primary mediator of the acute phase response and induces fever?', '["IL-1", "IL-2", "IL-3", "IL-4", "IL-10"]', 0, 'Block 5 — Q176. IL-1, IL-6, and TNF-alpha are pro-inflammatory.', 176),
    (v_inter_id, 'Transplant rejection that occurs within minutes due to pre-existing antibodies is called:', '["Hyperacute rejection", "Acute rejection", "Chronic rejection", "Graft-versus-host disease", "Innate rejection"]', 0, 'Block 5 — Q177. Hyperacute is an antibody-mediated Type II reaction.', 177),
    (v_inter_id, 'A deficiency in CD40L leading to the inability to class switch from IgM to IgG is characteristic of:', '["SCID", "Hyper-IgM syndrome", "Wiskott-Aldrich syndrome", "Ataxia-telangiectasia", "Job syndrome"]', 1, 'Block 5 — Q178. Failure of CD40L-CD40 interaction.', 178),
    (v_inter_id, 'The enzyme NADPH oxidase is deficient in which immunodeficiency, leading to recurrent catalase-positive infections?', '["Chronic granulomatous disease (CGD)", "Chédiak-Higashi syndrome", "Leukocyte adhesion deficiency", "SCID", "Bruton syndrome"]', 0, 'Block 5 — Q179. CGD fails the oxidative burst.', 179),
    (v_inter_id, 'Which immunoglobulin is found in secretions like breast milk, tears, and saliva?', '["IgG", "IgA", "IgM", "IgE", "IgD"]', 1, 'Block 5 — Q180. Secretory IgA is a dimer.', 180),
    (v_anatomy_id, 'Which nerve passes through the carpal tunnel and is compressed in Carpal Tunnel Syndrome?', '["Ulnar nerve", "Radial nerve", "Median nerve", "Axillary nerve", "Musculocutaneous nerve"]', 2, 'Block 5 — Q181. Median nerve provides sensation to the first 3.5 digits.', 181),
    (v_anatomy_id, 'A "Waiters tip" deformity (arm adducted, internally rotated, elbow extended) is caused by injury to which part of the brachial plexus?', '["Upper trunk (C5-C6)", "Lower trunk (C8-T1)", "Posterior cord", "Medial cord", "Lateral cord"]', 0, 'Block 5 — Q182. Erb''s palsy is an upper trunk injury.', 182),
    (v_anatomy_id, 'The "Sartorius" muscle is innervated by which nerve?', '["Femoral nerve", "Obturator nerve", "Sciatic nerve", "Tibial nerve", "Common peroneal nerve"]', 0, 'Block 5 — Q183. Femoral nerve innervates the anterior compartment of the thigh.', 183),
    (v_anatomy_id, 'Failure of the processus vaginalis to close in a male can lead to:', '["Hydrocele", "Indirect inguinal hernia", "Direct inguinal hernia", "Varicocele", "Spermatocele"]', 1, 'Block 5 — Q184. Patent processus vaginalis allows hernia sac to descend.', 184),
    (v_anatomy_id, 'Which ligament prevents the femur from sliding backward on the tibia (posterior displacement)?', '["ACL", "PCL", "MCL", "LCL", "Patellar ligament"]', 1, 'Block 5 — Q185. PCL is the primary constraint to posterior translation.', 185),
    (v_anatomy_id, 'A patient cannot abduct their thigh. Which muscle and nerve are likely injured?', '["Gluteus maximus; Inferior gluteal nerve", "Gluteus medius; Superior gluteal nerve", "Adductor longus; Obturator nerve", "Biceps femoris; Sciatic nerve", "Pectineus; Femoral nerve"]', 1, 'Block 5 — Q186. Gluteus medius/minimus (Superior Gluteal Nerve) abduct the hip.', 186),
    (v_anatomy_id, 'Which structure passes through the diaphragm at the level of T12?', '["Inferior vena cava", "Esophagus", "Aorta", "Phrenic nerve", "Vagus nerve"]', 2, 'Block 5 — Q187. I8, 10E, A12 (IVC at T8, Esophagus at T10, Aorta at T12).', 187),
    (v_anatomy_id, 'The "Great Saphenous Vein" drains into which vein in the groin?', '["Popliteal vein", "Femoral vein", "Internal iliac vein", "External iliac vein", "Common iliac vein"]', 1, 'Block 5 — Q188. It joins the femoral vein at the saphenous opening.', 188),
    (v_anatomy_id, 'Which cranial nerve passes through the Foramen Rotundum?', '["CN V1", "CN V2", "CN V3", "CN VII", "CN IX"]', 1, 'Block 5 — Q189. Maxillary nerve (V2). V1 is Superior Orbital Fissure, V3 is Foramen Ovale.', 189),
    (v_anatomy_id, 'Damage to the recurrent laryngeal nerve would most likely cause:', '["Loss of taste", "Difficulty swallowing", "Hoarseness", "Loss of sensation to the face", "Torticollis"]', 2, 'Block 5 — Q190. It innervates all intrinsic muscles of the larynx except the cricothyroid.', 190),
    (v_anatomy_id, 'The "Appendix" is classically located at which point on the abdominal wall?', '["McBurney''s point", "Murphy''s point", "Lanz point", "Kehr''s point", "Grey-Turner''s point"]', 0, 'Block 5 — Q191. 1/3 the distance from ASIS to umbilicus.', 191),
    (v_anatomy_id, 'Which pharyngeal arch gives rise to the stylopharyngeus muscle?', '["First arch", "Second arch", "Third arch", "Fourth arch", "Sixth arch"]', 2, 'Block 5 — Q192. CN IX (Glossopharyngeal) and the 3rd arch.', 192),
    (v_anatomy_id, 'Which nerve provides sensation to the medial aspect of the thigh?', '["Femoral nerve", "Obturator nerve", "Lateral femoral cutaneous nerve", "Sciatic nerve", "Genitofemoral nerve"]', 1, 'Block 5 — Q193. Obturator nerve innervates the medial thigh.', 193),
    (v_inter_id, 'The "Neural Crest" cells give rise to which of the following?', '["CNS neurons", "Melanocytes", "Skeletal muscle", "Vertebrae", "Liver cells"]', 1, 'Block 5 — Q194. Melanocytes, Schwann cells, Adrenal medulla, etc.', 194),
    (v_inter_id, 'Which type of collagen is found in skin, bone, and tendons?', '["Type I", "Type II", "Type III", "Type IV", "Type V"]', 0, 'Block 5 — Q195. Type I is the most abundant.', 195),
    (v_inter_id, 'Mutation in the gene for Type I Collagen leads to:', '["Ehlers-Danlos syndrome", "Osteogenesis imperfecta", "Marfan syndrome", "Alport syndrome", "Goodpasture syndrome"]', 1, 'Block 5 — Q196. Brittle bone disease.', 196),
    (v_inter_id, 'A neonate has a scaphoid abdomen and respiratory distress. Bowel sounds are heard in the chest. What is the diagnosis?', '["Pyloric stenosis", "Congenital diaphragmatic hernia", "Esophageal atresia", "Duodenal atresia", "Malrotation"]', 1, 'Block 5 — Q197. Failure of pleuroperitoneal fold closure.', 197),
    (v_inter_id, 'Which structure is a remnant of the urachus in adults?', '["Ligamentum teres", "Medial umbilical ligament", "Median umbilical ligament", "Lateral umbilical ligament", "Ligamentum venosum"]', 2, 'Block 5 — Q198. Median umbilical ligament.', 198),
    (v_inter_id, 'The "Left recurrent laryngeal nerve" loops under which structure?', '["Right subclavian artery", "Arch of the aorta", "Ligamentum arteriosum", "Left primary bronchus", "Esophagus"]', 1, 'Block 5 — Q199. It loops under the aortic arch.', 199),
    (v_inter_id, 'Which organelle is responsible for post-translational modification and sorting of proteins?', '["Rough ER", "Smooth ER", "Golgi apparatus", "Lysosome", "Peroxisome"]', 2, 'Block 5 — Q200. Golgi is the "UPS" of the cell.', 200),
    (v_path_id, 'A 68-year-old male with a history of HTN and smoking presents with sudden, tearing chest pain radiating to his back. His BP is 180/100 mmHg. What is the most likely diagnosis?', '["Myocardial Infarction", "Aortic Dissection", "Pulmonary Embolism", "Pneumothorax", "Esophageal Rupture"]', 1, 'Block 6 — Q201. Explanation: Tearing back pain in a hypertensive patient is classic for aortic dissection.', 201),
    (v_path_id, 'Which pathology is characterized by "Aschoff bodies" and "Anitschkow cells" in the myocardium?', '["Infective Endocarditis", "Rheumatic Heart Disease", "Dilated Cardiomyopathy", "Hypertrophic Cardiomyopathy", "Restrictive Cardiomyopathy"]', 1, 'Block 6 — Q202. Explanation: Rheumatic fever/heart disease is associated with Aschoff bodies.', 202),
    (v_path_id, 'A 50-year-old smoker presents with heavy, non-productive cough for 4 months for the past 2 years. Biopsy shows a Reid Index > 0.5. What is the diagnosis?', '["Emphysema", "Asthma", "Chronic Bronchitis", "Bronchiectasis", "Silicosis"]', 2, 'Block 6 — Q203. Explanation: Reid index > 0.5 is diagnostic for chronic bronchitis.', 203),
    (v_path_id, 'A child presents with periorbital edema and "cola-colored" urine 2 weeks after a sore throat. Lab shows low C3 levels. What is the most likely diagnosis?', '["Minimal Change Disease", "Membranous Nephropathy", "Post-streptococcal Glomerulonephritis (PSGN)", "IgA Nephropathy", "Goodpasture Syndrome"]', 2, 'Block 6 — Q204. Explanation: PSGN occurs after Strep infection with subepithelial "humps" on EM.', 204),
    (v_path_id, 'Which colon pathology is characterized by "string sign" on barium swallow and "creeping fat" in the mesentery?', '["Ulcerative Colitis", "Crohn''s Disease", "Diverticulitis", "Ischemic Colitis", "Celiac Disease"]', 1, 'Block 6 — Q205. Explanation: Crohn disease has skip lesions and transmural inflammation.', 205),
    (v_path_id, 'A patient with "Auer rods" in their bone marrow blasts is most likely diagnosed with:', '["Acute Lymphoblastic Leukemia (ALL)", "Acute Myeloid Leukemia (AML)", "Chronic Myeloid Leukemia (CML)", "Chronic Lymphocytic Leukemia (CLL)", "Hodgkin Lymphoma"]', 1, 'Block 6 — Q206. Auer rods = AML (specifically M3 type).', 206),
    (v_path_id, 'What is the characteristic chromosomal translocation in Chronic Myeloid Leukemia (CML)?', '["t(8;14)", "t(9;22)", "t(14;18)", "t(11;14)", "t(15;17)"]', 1, 'Block 6 — Q207. Philadelphia chromosome (BCR-ABL fusion).', 207),
    (v_path_id, 'Which kidney pathology is characterized by "spike and dome" appearance on silver stain?', '["Minimal change disease", "FSGS", "Membranous nephropathy", "MPGN", "Diabetic nephropathy"]', 2, 'Block 6 — Q208. Membranous is the most common cause of nephrotic syndrome in adults.', 208),
    (v_path_id, 'A patient with "Apple-core lesion" on barium enema likely has:', '["Colon cancer", "Diverticulosis", "Intussusception", "Volvulus", "Hirschsprung disease"]', 0, 'Block 6 — Q209. Distal colon cancer narrows the lumen.', 209),
    (v_path_id, 'Which brain tumor in children is located in the posterior fossa and shows "Homer-Wright rosettes"?', '["Pilocytic astrocytoma", "Medulloblastoma", "Ependymoma", "Craniopharyngioma", "Glioblastoma"]', 1, 'Block 6 — Q210. Medulloblastoma is a highly malignant primitive neuroectodermal tumor.', 210),
    (v_path_id, 'A 60-year-old male has "B-symptoms" (fever, night sweats) and a massively enlarged spleen. Lab shows t(9;22) and low LAP score. What is the diagnosis?', '["CML", "AML", "Polycythemia vera", "Essential thrombocythemia", "Myelofibrosis"]', 0, 'Block 6 — Q211. Low Leukocyte Alkaline Phosphatase (LAP) distinguishes CML from leukemoid reaction.', 211),
    (v_path_id, 'Which type of breast cancer is invasive, often unilateral, and consists of small cells in a single-file "Indian file" pattern?', '["Invasive ductal carcinoma", "Invasive lobular carcinoma", "Medullary carcinoma", "Mucinous carcinoma", "Paget disease"]', 1, 'Block 6 — Q212. Loss of E-cadherin is common in lobular carcinoma.', 212),
    (v_path_id, 'A patient with cirrhosis, bronze skin, and diabetes likely has:', '["Wilson disease", "Hemochromatosis", "Alpha-1 antitrypsin deficiency", "Primary biliary cholangitis", "Alcoholic hepatitis"]', 1, 'Block 6 — Q213. Iron overload (Bronze diabetes).', 213),
    (v_path_id, 'Which pathology is characterized by "wire loop" glomerular capillaries in a patient with SLE?', '["Minimal change disease", "Diffuse proliferative glomerulonephritis (DPGN)", "Membranous nephropathy", "FSGS", "IgA nephropathy"]', 1, 'Block 6 — Q214. DPGN (WHO class IV lupus nephritis).', 214),
    (v_path_id, 'A 45-year-old male with long-standing ulcerative colitis is at high risk for which biliary condition?', '["Choledocholithiasis", "Primary sclerosing cholangitis (PSC)", "Primary biliary cholangitis (PBC)", "Biliary atresia", "Ascending cholangitis"]', 1, 'Block 6 — Q215. PSC is strongly associated with UC.', 215),
    (v_path_id, 'Which bone tumor is characterized by an "onion skin" appearance on X-ray?', '["Osteosarcoma", "Ewing sarcoma", "Osteochondroma", "Gaint cell tumor", "Osteoma"]', 1, 'Block 6 — Q216. Ewing sarcoma (t(11;22)).', 216),
    (v_path_id, 'A biopsy of a patient with Parkinson disease would show:', '["Neurofibrillary tangles", "Lewy bodies", "Pick bodies", "Negri bodies", "Prion plaques"]', 1, 'Block 6 — Q217. Lewy bodies (alpha-synuclein).', 217),
    (v_path_id, 'Which glomerular disease is associated with HIV, heroin use, and obesity?', '["Minimal change disease", "FSGS", "Membranous nephropathy", "MPGN", "IgA nephropathy"]', 1, 'Block 6 — Q218. Focal Segmental Glomerulosclerosis.', 218),
    (v_path_id, 'A patient with sudden, painless monocular vision loss and a "cherry-red spot" on the macula has:', '["Central retinal vein occlusion", "Central retinal artery occlusion", "Retinal detachment", "Macular degeneration", "Glaucoma"]', 1, 'Block 6 — Q219. CRAO is an emergency.', 219),
    (v_path_id, 'Which brain tumor shows "pseudopalisading" necrosis on histology?', '["Meningioma", "Glioblastoma multiforme", "Oligodendroglioma", "Astrocytoma", "Schwannoma"]', 1, 'Block 6 — Q220. GBM is the most common primary malignant brain tumor in adults.', 220),
    (v_path_id, 'A patient with "tram-track" appearance in the kidney on silver stain likely has:', '["MPGN type I", "Membranous nephropathy", "Post-strep GN", "Minimal change disease", "Goodpasture"]', 0, 'Block 6 — Q221. Membranoproliferative GN type I involves subendothelial deposits.', 221),
    (v_path_id, 'Which disease is caused by an autoantibody against the Acetylcholine Receptor?', '["Lambert-Eaton syndrome", "Myasthenia gravis", "Multiple sclerosis", "Guillain-Barre syndrome", "Amyotrophic lateral sclerosis"]', 1, 'Block 6 — Q222. MG involves fatiguing muscle weakness.', 222),
    (v_path_id, 'What is the characteristic histology of a Meningioma?', '["Psammoma bodies and whorled pattern", "Fried-egg appearance", "Chicken-wire capillaries", "Rosenthal fibers", "Perivascular pseudorosettes"]', 0, 'Block 6 — Q223. Meningiomas are usually benign and arise from the arachnoid cells.', 223),
    (v_path_id, 'A patient with "Charcot-Marie-Tooth" disease has a defect in:', '["Myelin protein synthesis", "Axonal transport", "Acetylcholine release", "Muscle contraction proteins", "Dopamine synthesis"]', 0, 'Block 6 — Q224. CMT is a group of hereditary peripheral neuropathies.', 224),
    (v_path_id, 'Which vascular disease is associated with "Segmental transmural inflammation with fibrinoid necrosis" and is often positive for HBsAg?', '["Temporal arteritis", "Takayasu arteritis", "Polyarteritis nodosa (PAN)", "Kawasaki disease", "Wegener granulomatosis"]', 2, 'Block 6 — Q225. PAN involves medium-sized vessels.', 225),
    (v_path_id, 'A patient with "strawberry tongue" and desquamating rash is likely suffering from:', '["Scarlet fever", "Kawasaki disease", "Toxic shock syndrome", "All of the above", "None of the above"]', 3, 'Block 6 — Q226. These are common findings in pediatric inflammatory conditions.', 226),
    (v_path_id, 'Which liver pathology is characterized by "Mallory-Denk bodies" and macrovesicular steatosis?', '["Wilson disease", "Alcoholic steatohepatitis", "Nonalcoholic fatty liver disease", "Hepatitis B", "Alpha-1 antitrypsin deficiency"]', 1, 'Block 6 — Q227. Mallory bodies are damaged intermediate filaments.', 227),
    (v_path_id, 'A 50-year-old male has "starry sky" appearance on lymph node biopsy. This is common in:', '["Follicular lymphoma", "Burkitt lymphoma", "Mantel cell lymphoma", "DLBCL", "Hodgkin lymphoma"]', 1, 'Block 6 — Q228. Burkitt lymphoma (t(8;14)) has high mitotic rate.', 228),
    (v_path_id, 'Which glomerular pathology shows "wire-looping" of capillaries?', '["DPGN", "PSGN", "MPGN", "IgA nephropathy", "Alport syndrome"]', 0, 'Block 6 — Q229. Lupus nephritis type IV.', 229),
    (v_path_id, 'A patient with "painless" jaundice and weight loss is found to have an enlarged, non-tender gallbladder. What is the diagnosis?', '["Choledocholithiasis", "Pancreatic cancer (head)", "Hepatocellular carcinoma", "Primary biliary cirrhosis", "Gilbert syndrome"]', 1, 'Block 6 — Q230. Courvoisier sign.', 230),
    (v_path_id, 'Which disease is characterized by destruction of the Beta cells in the pancreas?', '["Type 1 Diabetes Mellitus", "Type 2 Diabetes Mellitus", "Insulinoma", "Glucagonoma", "Cystic Fibrosis"]', 0, 'Block 6 — Q231. Type 1 DM is an autoimmune destruction.', 231),
    (v_path_id, 'A patient with "Multiple Myeloma" would show which clinical findings?', '["Anemia", "Bone pain/Fractures", "Hypercalcemia", "Renal failure", "All of the above (CRAB)"]', 4, 'Block 6 — Q232. CRAB: Calcium, Renal, Anemia, Bone.', 232),
    (v_path_id, 'Which pathology is characterized by "Councilman bodies" in the liver?', '["Viral hepatitis", "Alcoholic hepatitis", "Autoimmune hepatitis", "Acetaminophen toxicity", "Yellow fever"]', 0, 'Block 6 — Q233. Councilman bodies are apoptotic hepatocytes.', 233),
    (v_path_id, 'A child with "abdominal mass," "hematuria," and "hypertension" likely has:', '["Neuroblastoma", "Wilms tumor", "RCC", "Polycystic kidney disease", "Hydronephrosis"]', 1, 'Block 6 — Q234. Nephroblastoma (Wilms tumor).', 234),
    (v_path_id, 'Which heart condition is characterized by a "Boot-shaped heart" on chest X-ray?', '["Transposition of great vessels", "Tetralogy of Fallot", "Tricuspid atresia", "VSD", "ASD"]', 1, 'Block 6 — Q235. TOF involves VSD, Overriding aorta, RVH, Pulmonary stenosis.', 235),
    (v_path_id, 'A patient with "smudge cells" on peripheral blood smear most likely has:', '["ALL", "CLL", "AML", "CML", "Multiple Myeloma"]', 1, 'Block 6 — Q236. CLL is characterized by fragile lymphocytes.', 236),
    (v_path_id, 'Which thyroid cancer is associated with RET mutations and produces Calcitonin?', '["Papillary", "Follicular", "Medullary", "Anaplastic", "Hurthle"]', 2, 'Block 6 — Q237. Medullary thyroid carcinoma arises from parafollicular C cells.', 237),
    (v_path_id, 'A biopsy from a patient with "Alzheimer disease" shows extra-cellular plaques containing:', '["Alpha-synuclein", "Tau protein", "Beta-amyloid", "Prions", "TDP-43"]', 2, 'Block 6 — Q238. A-beta plaques; Neurofibrillary tangles contain Tau.', 238),
    (v_path_id, 'Which colon condition is characterized by "pseudopolyps" and "lead-pipe" appearance on X-ray?', '["Crohn disease", "Ulcerative colitis", "Ischemic colitis", "Infectious colitis", "Diverticulitis"]', 1, 'Block 6 — Q239. UC lacks haustra, leading to lead-pipe appearance.', 239),
    (v_path_id, 'A "Crescentic glomerulonephritis" is indicative of:', '["Minimal change disease", "Rapidly progressive GN (RPGN)", "Post-strep GN", "Membranous nephropathy", "Diabetic nephropathy"]', 1, 'Block 6 — Q240. RPGN involves crescents of fibrin and plasma proteins.', 240),
    (v_physio_id, 'What is the primary effect of ADH (Vasopressin) on the kidney?', '["Increase Na+ reabsorption", "Increase water permeability of the collecting duct (AQP2)", "Decrease GFR", "Increase K+ secretion", "Inhibit renin release"]', 1, 'Block 7 — Q241. ADH inserts aquaporin channels.', 241),
    (v_physio_id, 'In a patient with metabolic acidosis, what is the expected compensatory response?', '["Bradypnea (low RR)", "Tachypnea (High RR - Kussmaul)", "Increase HCO3- reabsorption", "Decrease H+ secretion", "None"]', 1, 'Block 7 — Q242. Respiratory compensation lowers PaCO2.', 242),
    (v_path_id, 'A patient with "Pheochromocytoma" should be treated with which drug before surgery?', '["Beta-blocker first", "Alpha-blocker first (Phenoxybenzamine)", "ACE inhibitor", "Calcium channel blocker", "Diuretic"]', 1, 'Block 7 — Q243. Alpha-blockade first to prevent hypertensive crisis.', 243),
    (v_physio_id, 'Which hormone is the primary stimulus for gallbladder contraction and pancreatic enzyme secretion?', '["Gastrin", "CCK", "Secretin", "GIP", "Glucagon"]', 1, 'Block 7 — Q244. CCK is released in response to fat/protein.', 244),
    (v_physio_id, 'What is the primary site of water reabsorption in the nephron?', '["Proximal tubule", "Loop of Henle", "Distal tubule", "Collecting duct", "Glomerulus"]', 0, 'Block 7 — Q245. 67% of water and Na+ are reabsorbed in the PCT.', 245),
    (v_physio_id, 'Which lung volume represents the volume of air inspired or expired during a normal breath?', '["Tidal volume", "Residual volume", "Functional residual capacity", "Vital capacity", "Inspiratory capacity"]', 0, 'Block 7 — Q246. TV is typically 500 mL.', 246),
    (v_physio_id, 'The "Frank-Starling law" of the heart states that:', '["Stroke volume increases with increased end-diastolic volume", "Heart rate increases with stroke volume", "Contractility decreases with stretch", "Afterload increases with preload", "Vagal tone reduces heart rate"]', 0, 'Block 7 — Q247. Increased stretch leads to stronger contraction.', 247),
    (v_physio_id, 'Where is the "Pacemaker" of the heart located?', '["AV node", "SA node", "Bundle of His", "Purkinje fibers", "Left atrium"]', 1, 'Block 7 — Q248. Sinoatrial node in the right atrium.', 248),
    (v_physio_id, 'Which cell in the stomach secretes Intrinsic Factor and Gastric Acid?', '["G-cell", "Chief cell", "Parietal cell", "Mucous cell", "D-cell"]', 2, 'Block 7 — Q249. Parietal cells secrete HCl and IF.', 249),
    (v_physio_id, 'What is the effect of Parathyroid Hormone (PTH) on the kidney?', '["Increase Ca2+ and PO43- reabsorption", "Increase Ca2+ reabsorption and decrease PO43- reabsorption", "Decrease Ca2+ and PO43- reabsorption", "Decrease Ca2+ reabsorption and increase PO43- reabsorption", "Increase water reabsorption"]', 1, 'Block 7 — Q250. PTH is phosphate-trashing.', 250),
    (v_physio_id, 'In metabolic alkalosis, the compensation involves:', '["Hypoventilation to increase PaCO2", "Hyperventilation to decrease PaCO2", "Increased RENAL H+ excretion", "Increased RENAL HCO3- excretion", "None"]', 0, 'Block 7 — Q251. Lowering RR preserves CO2.', 251),
    (v_physio_id, 'The "Ejection Fraction" is defined as:', '["SV / EDV", "EDV / SV", "SV / ESV", "CO / HR", "MAP / TPR"]', 0, 'Block 7 — Q252. Normal EF is >55%.', 252),
    (v_physio_id, 'Which factor is responsible for the closing of the ductus arteriosus at birth?', '["Decreased O2", "Increased Prostaglandin E2", "Decreased Prostaglandin E2 / Increased O2", "Increased CO2", "Decreased blood pressure"]', 2, 'Block 7 — Q253. Indomethacin can be used to close it pharmacologically.', 253),
    (v_physio_id, 'What is the primary buffer system in the extracellular fluid?', '["Phosphate buffer", "Protein buffer", "Hemoglobin buffer", "Bicarbonate-CO2 buffer", "Ammonium buffer"]', 3, 'Block 7 — Q254. HCO3- / CO2 is the main ECF buffer.', 254),
    (v_physio_id, 'Which hormone is produced by the Corpus Luteum and maintains the pregnancy in the first trimester?', '["Estrogen", "Progesterone", "hCG", "LH", "FSH"]', 1, 'Block 7 — Q255. Progesterone prevents menstruation.', 255),
    (v_physio_id, 'What is the effect of sympathetic stimulation on the bronchial smooth muscle?', '["Constriction", "Relaxation (Bronchodilation)", "Increased secretion", "No effect", "Decreased surfactant"]', 1, 'Block 7 — Q256. Beta-2 adrenergic receptors cause relaxation.', 256),
    (v_physio_id, 'The "Resistance" vessels of the circulatory system are:', '["Aorta", "Arteries", "Arterioles", "Capillaries", "Veins"]', 2, 'Block 7 — Q257. Arterioles provide the most resistance and MAP control.', 257),
    (v_physio_id, 'A patient with "Respiratory Acidosis" would have which of the following labs?', '["High pH, High CO2", "Low pH, High CO2", "Low pH, Low CO2", "High pH, Low CO2", "Normal pH, Normal CO2"]', 1, 'Block 7 — Q258. Hypoventilation causes CO2 accumulation.', 258),
    (v_physio_id, 'Which hormone stimulates the "Let-down" reflex during breastfeeding?', '["Prolactin", "Oxytocin", "Estrogen", "Progesterone", "TSH"]', 1, 'Block 7 — Q259. Oxytocin causes milk ejection; Prolactin causes milk production.', 259),
    (v_physio_id, 'What is the main role of the "Juxtaglomerular Apparatus"?', '["Bile production", "Renin secretion and BP regulation", "Erythropoietin secretion", "Concentrating urine", "Filtration of proteins"]', 1, 'Block 7 — Q260. JG cells sense low pressure and release renin.', 260),
    (v_physio_id, 'Which part of the heart has the slowest conduction velocity?', '["SA node", "Atria", "AV node", "Purkinje fibers", "Ventricles"]', 2, 'Block 7 — Q261. AV node delay allows for ventricular filling.', 261),
    (v_physio_id, 'What is the effect of Angiotensin II on the efferent arteriole?', '["Vasodilation", "Vasoconstriction", "No effect", "Inhibition", "Increased RPF"]', 1, 'Block 7 — Q262. Constriction of the efferent arteriole maintains GFR.', 262),
    (v_path_id, 'A patient with "Addison disease" would show which electrolyte abnormalities?', '["Hypernatremia, Hypokalemia", "Hyponatremia, Hyperkalemia", "Hypercalcemia", "Hypocalcemia", "Normal"]', 1, 'Block 7 — Q263. Low aldosterone leads to Na loss and K retention.', 263),
    (v_path_id, 'Which condition is characterized by a "moon face" and "buffalo hump"?', '["Addison disease", "Cushing syndrome", "Graves disease", "Conn syndrome", "Diabetes insipidus"]', 1, 'Block 7 — Q264. Hypercortisolism.', 264),
    (v_physio_id, 'Which hormone is secreted by the atria in response to stretch and promotes Na+ excretion?', '["ADH", "Aldosterone", "ANP", "Renin", "Cortisol"]', 2, 'Block 7 — Q265. Atrial Natriuretic Peptide.', 265),
    (v_physio_id, 'Where is the primary site of Vitamin B12 absorption?', '["Stomach", "Duodenum", "Jejunum", "Terminal ileum", "Colon"]', 3, 'Block 7 — Q266. Requires intrinsic factor from the stomach.', 266),
    (v_physio_id, 'What is the functional unit of the kidney?', '["Nephron", "Glomerulus", "Kidney lobe", "Tubule", "Ureter"]', 0, 'Block 7 — Q267. The nephron handles filtration and reabsorption.', 267),
    (v_physio_id, 'Which hormone is inhibited by Alkohol, leading to increased urine production?', '["Aldosterone", "ADH", "ANP", "Oxytocin", "Insulin"]', 1, 'Block 7 — Q268. Alcohol inhibits ADH release from the posterior pituitary.', 268),
    (v_physio_id, 'The "Absolute Refractory Period" of a cardiac myocyte occurs during:', '["Phase 0, 1, 2, and part of 3", "Phase 4 only", "Phase 0 and 1 only", "The entire action potential", "Phase 3 only"]', 0, 'Block 7 — Q269. The cell cannot be restimulated.', 269),
    (v_physio_id, 'What is the primary determinant of "Systemic Vascular Resistance" (SVR)?', '["Cardiac output", "Arteriolar diameter", "Venous return", "Pulse pressure", "Blood volume"]', 1, 'Block 7 — Q270. Small changes in radius lead to large changes in resistance (1/r^4).', 270),
    (v_physio_id, 'Which hormone acts on the "Chief cells" to stimulate Pepsinogen release?', '["Gastrin", "Secretin", "CCK", "Somatostatin", "Histamine"]', 0, 'Block 7 — Q271. Gastrin and vagal stimulation increase pepsinogen.', 271),
    (v_physio_id, 'A patient with "Hyper-parathyroidism" would have what effect on bone?', '["Increased bone density", "Increased bone resorption (Osteitis fibrosa cystica)", "Bone formation", "No effect", "Decreased osteoclast activity"]', 1, 'Block 7 — Q272. PTH stimulates osteoclasts indirectly.', 272),
    (v_physio_id, 'What is the effect of "Insulin" on potassium levels?', '["Increase serum K+", "Decrease serum K+ (shift into cells)", "No effect", "Increase renal K+ excretion", "Decrease renal K+ excretion"]', 1, 'Block 7 — Q273. Insulin/Glucose therapy is used for hyperkalemia.', 273),
    (v_physio_id, 'The "Blood-Brain Barrier" is formed by which cell type?', '["Astrocytes", "Microglia", "Oligodendrocytes", "Ependymal cells", "Capillary endothelial cells with tight junctions"]', 4, 'Block 7 — Q274. Foot processes of astrocytes also support it.', 274),
    (v_physio_id, 'Which hormone is increased in response to low serum Calcium?', '["Calcitonin", "PTH", "Vitamin D", "Aldosterone", "Insulin"]', 1, 'Block 7 — Q275. PTH raises serum Calcium.', 275),
    (v_physio_id, 'What is the main source of energy for the brain during prolonged starvation?', '["Glucose", "Fatty acids", "Ketone bodies", "Amino acids", "Lactate"]', 2, 'Block 7 — Q276. Brain can use acetoacetate and beta-hydroxybutyrate.', 276),
    (v_physio_id, 'Which hormone is responsible for the "Luteal Phase" of the menstrual cycle?', '["LH", "FSH", "Estrogen", "Progesterone", "GnRH"]', 3, 'Block 7 — Q277. Progesterone is the dominant hormone after ovulation.', 277),
    (v_physio_id, 'What is the effect of "Acetazolamide" on the urine pH?', '["Acidifies", "Alkalinizes", "No effect", "Bicarbonate reabsorption", "None"]', 1, 'Block 7 — Q278. Inhibits carbonic anhydrase, leading to HCO3- loss in urine.', 278),
    (v_physio_id, 'Which clotting factor is inhibited by "Warfarin"?', '["Factor II, VII, IX, X", "Factor VIII", "Factor XII", "Factor XI", "Factor V"]', 0, 'Block 7 — Q279. Inhibits Vitamin K epoxide reductase.', 279),
    (v_physio_id, 'A patient with "Hyperventilation" (due to anxiety) will develop:', '["Respiratory acidosis", "Respiratory alkalosis", "Metabolic acidosis", "Metabolic alkalosis", "None"]', 1, 'Block 7 — Q280. Loss of CO2 raises pH.', 280);

